INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u180, 4, '【章节】系统初始化', '', 'text', NULL, 'bash', '', 0, 310, 0);
