INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u180, 4, '正文', '', 'text', 'init接下来会打开6个终端，以便用户登录系统。在inittab中的以下6行就是定义了6个终端：', 'bash', '', 0, 430, 0);
