INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u180, 4, '正文', '', 'text', 'Linux 的账号验证程序是 login，login 会接收 mingetty 传来的用户名作为用户名参数。', 'bash', '', 0, 540, 0);
