INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u180, 4, '正文', '', 'text', 'Linux预设提供了六个命令窗口终端机让我们来登录。', 'bash', '', 0, 590, 0);
