INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u180, 4, '正文', '', 'text', '当你进入命令窗口界面后再返回图形界面只要按下Ctrl + Alt + F7 就回来了。', 'bash', '', 0, 620, 0);
