INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u180, 4, '正文', '', 'text', '关机指令为：shutdown ，你可以man shutdown 来看一下帮助文档。', 'bash', '', 0, 670, 0);
SET @u248 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u180, 4, '正文', '', 'text', '例如你可以运行如下命令关机：', 'bash', '', 0, 680, 0);
SET @u249 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u180, 4, '代码示例', '', 'code', 'sync 将数据由内存同步到硬盘中。\n\nshutdown 关机指令，你可以man shutdown 来看一下帮助文档。例如你可以运行如下命令关机：\n\nshutdown –h 10 ‘This server will shutdown after 10 mins’ 这个命令告诉大家，计算机将在10分钟后关机，并且会显示在登陆用户的当前屏幕中。\n\nshutdown –h now 立马关机\n\nshutdown –h 20:25 系统会在今天20:25关机\n\nshutdown –h +10 十分钟后关机\n\nshutdown –r now 系统立马重启\n\nshutdown –r +10 系统十分钟后重启\n\nreboot 就是重启，等同于 shutdown –r now\n\nhalt 关闭系统，等同于shutdown –h now 和 poweroff', 'bash', '', 0, 690, 0);
SET @u250 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u180, 4, '正文', '', 'text', '最后总结一下，不管是重启系统还是关闭系统，首先要运行 sync 命令，把内存中的数据写到磁盘中。', 'bash', '', 0, 700, 0);
SET @u251 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u180, 4, '正文', '', 'text', '关机的命令有 shutdown –h now halt poweroff 和 init 0 , 重启系统的命令有 shutdown –r now reboot init 6。', 'bash', '', 0, 710, 0);
SET @u252 := LAST_INSERT_ID();
