INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u408, 4, '代码示例', '', 'code', '[root@www ~]# cd /var/mail <==注意，/var/mail是一个链接档\n\n[root@www mail]# pwd\n\n/var/mail <==列出目前的工作目录\n\n[root@www mail]# pwd -P\n\n/var/spool/mail <==怎么回事？有没有加 -P 差很多～\n\n[root@www mail]# ls -ld /var/mail\n\nlrwxrwxrwx 1 root root 10 Sep 4 17:54 /var/mail -> spool/mail\n\n# 看到这里应该知道为啥了吧？因为 /var/mail 是链接档，链接到 /var/spool/mail \n\n# 所以，加上 pwd -P 的选项后，会不以链接档的数据显示，而是显示正确的完整路径啊！', 'bash', '', 0, 410, 0);
