INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u590, 4, '正文', '', 'text', '完成用户管理的工作有许多种方法，但是每一种方法实际上都是对有关的系统文件进行修改。', 'bash', '', 0, 1070, 0);
