INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u782, 4, '代码示例', '', 'code', '[root@AY120919111755c246621 tmp]# fdisk -l\n\nDisk /dev/xvda: 21.5 GB, 21474836480 bytes\n\n255 heads, 63 sectors/track, 2610 cylinders\n\nUnits = cylinders of 16065 * 512 = 8225280 bytes\n\nSector size (logical/physical): 512 bytes / 512 bytes\n\nI/O size (minimum/optimal): 512 bytes / 512 bytes\n\nDisk identifier: 0x00000000\n\n Device Boot Start End Blocks Id System\n\n/dev/xvda1 * 1 2550 20480000 83 Linux\n\n/dev/xvda2 2550 2611 490496 82 Linux swap / Solaris\n\nDisk /dev/xvdb: 21.5 GB, 21474836480 bytes\n\n255 heads, 63 sectors/track, 2610 cylinders\n\nUnits = cylinders of 16065 * 512 = 8225280 bytes\n\nSector size (logical/physical): 512 bytes / 512 bytes\n\nI/O size (minimum/optimal): 512 bytes / 512 bytes\n\nDisk identifier: 0x56f40944\n\n Device Boot Start End Blocks Id System\n\n/dev/xvdb2 1 2610 20964793+ 83 Linux', 'bash', '', 0, 620, 0);
SET @u845 := LAST_INSERT_ID();
