INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u782, 4, '代码示例', '', 'code', '[root@www ~]# df / <==注意：重点在找出磁盘文件名而已\n\nFilesystem 1K-blocks Used Available Use% Mounted on\n\n/dev/hdc2 9920624 3823168 5585388 41% /\n\n[root@www ~]# fdisk /dev/hdc <==仔细看，不要加上数字喔！\n\nThe number of cylinders for this disk is set to 5005.\n\nThere is nothing wrong with that, but this is larger than 1024,\n\nand could in certain setups cause problems with:\n\n1) software that runs at boot time (e.g., old versions of LILO)\n\n2) booting and partitioning software from other OSs\n\n (e.g., DOS FDISK, OS/2 FDISK)\n\nCommand (m for help): <==等待你的输入！', 'bash', '', 0, 650, 0);
SET @u848 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u782, 4, '正文', '', 'text', '输入 m 后，就会看到底下这些命令介绍', 'bash', '', 0, 660, 0);
SET @u849 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u782, 4, '代码示例', '', 'code', 'Command (m for help): m <== 输入 m 后，就会看到底下这些命令介绍\n\nCommand action\n\n a toggle a bootable flag\n\n b edit bsd disklabel\n\n c toggle the dos compatibility flag\n\n d delete a partition <==删除一个partition\n\n l list known partition types\n\n m print this menu\n\n n add a new partition <==新增一个partition\n\n o create a new empty DOS partition table\n\n p print the partition table <==在屏幕上显示分割表\n\n q quit without saving changes <==不储存离开fdisk程序\n\n s create a new empty Sun disklabel\n\n t change a partition\'s system id\n\n u change display/entry units\n\n v verify the partition table\n\n w write table to disk and exit <==将刚刚的动作写入分割表\n\n x extra functionality (experts only)', 'bash', '', 0, 670, 0);
SET @u850 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u782, 4, '正文', '', 'text', '离开 fdisk 时按下 q，那么所有的动作都不会生效！相反的， 按下w就是动作生效的意思。', 'bash', '', 0, 680, 0);
SET @u851 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u782, 4, '代码示例', '', 'code', 'Command (m for help): p <== 这里可以输出目前磁盘的状态\n\nDisk /dev/hdc: 41.1 GB, 41174138880 bytes <==这个磁盘的文件名与容量\n\n255 heads, 63 sectors/track, 5005 cylinders <==磁头、扇区与磁柱大小\n\nUnits = cylinders of 16065 * 512 = 8225280 bytes <==每个磁柱的大小\n\n Device Boot Start End Blocks Id System\n\n/dev/hdc1 * 1 13 104391 83 Linux\n\n/dev/hdc2 14 1288 10241437+ 83 Linux\n\n/dev/hdc3 1289 1925 5116702+ 83 Linux\n\n/dev/hdc4 1926 5005 24740100 5 Extended\n\n/dev/hdc5 1926 2052 1020096 82 Linux swap / Solaris\n\n# 装置文件名 启动区否 开始磁柱 结束磁柱 1K大小容量 磁盘分区槽内的系统\n\nCommand (m for help): q', 'bash', '', 0, 690, 0);
SET @u852 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u782, 4, '正文', '', 'text', '想要不储存离开吗？按下 q 就对了！不要随便按 w 啊！', 'bash', '', 0, 700, 0);
SET @u853 := LAST_INSERT_ID();
