INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u985, 4, '代码示例', '', 'code', '[root@www ~]# yum remove pam-devel\n\nSetting up Remove Process\n\nResolving Dependencies <==同样的，先解决属性相依的问题\n\n--> Running transaction check\n\n---> Package pam-devel.i386 0:0.99.6.2-4.el5 set to be erased\n\n--> Finished Dependency Resolution\n\nDependencies Resolved\n\n=============================================================================\n\n Package Arch Version Repository Size\n\n=============================================================================\n\nRemoving:\n\n pam-devel i386 0.99.6.2-4.el5 installed 495 k\n\nTransaction Summary\n\n=============================================================================\n\nInstall 0 Package(s)\n\nUpdate 0 Package(s)\n\nRemove 1 Package(s) <==还好，并没有属性相依的问题，单纯移除一个软件\n\nIs this ok [y/N]: y\n\nDownloading Packages:\n\nRunning rpm_check_debug\n\nRunning Transaction Test\n\nFinished Transaction Test\n\nTransaction Test Succeeded\n\nRunning Transaction\n\n Erasing : pam-devel ######################### [1/1]\n\nRemoved: pam-devel.i386 0:0.99.6.2-4.el5\n\nComplete!', 'bash', '', 0, 300, 0);
SET @u1016 := LAST_INSERT_ID();
