INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1628, 4, '正文', '', 'text', 'case ... esac 为多选择语句，与其他语言中的 switch ... case 语句类似，是一种多分支选择结构，每个 case 分支用右圆括号开始，用两个分号 ;; 表示 break，即执行结束，跳出整个 case ... esac 语句，esac（就是 case 反过来）作为结束标记。', 'bash', '', 0, 740, 0);
SET @u1703 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1628, 4, '正文', '', 'text', '可以用 case 语句匹配一个值与一个模式，如果匹配成功，执行相匹配的命令。', 'bash', '', 0, 750, 0);
SET @u1704 := LAST_INSERT_ID();
