INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1844, 4, '正文', '', 'text', '配置nginx.conf\n\n，将/usr/local/webserver/nginx/conf/nginx.conf替换为以下内容', 'bash', '', 0, 340, 0);
SET @u1879 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1844, 4, '代码示例', '', 'code', '[root@bogon conf]# cat /usr/local/webserver/nginx/conf/nginx.conf\n\nuser www www;\n\nworker_processes 2; #设置值和CPU核心数一致\n\nerror_log /usr/local/webserver/nginx/logs/nginx_error.log crit; #日志位置和日志级别\n\npid /usr/local/webserver/nginx/nginx.pid;\n\n#Specifies the value for maximum file descriptors that can be opened by this process.\n\nworker_rlimit_nofile 65535;\n\nevents\n\n{\n\n use epoll;\n\n worker_connections 65535;\n\n}\n\nhttp\n\n{\n\n include mime.types;\n\n default_type application/octet-stream;\n\n log_format main \'$remote_addr - $remote_user [$time_local] "$request" \'\n\n \'$status $body_bytes_sent "$http_referer" \'\n\n \'"$http_user_agent" $http_x_forwarded_for\';\n\n \n\n#charset gb2312;\n\n \n\n server_names_hash_bucket_size 128;\n\n client_header_buffer_size 32k;\n\n large_client_header_buffers 4 32k;\n\n client_max_body_size 8m;\n\n \n\n sendfile on;\n\n tcp_nopush on;\n\n keepalive_timeout 60;\n\n tcp_nodelay on;\n\n fastcgi_connect_timeout 300;\n\n fastcgi_send_timeout 300;\n\n fastcgi_read_timeout 300;\n\n fastcgi_buffer_size 64k;\n\n fastcgi_buffers 4 64k;\n\n fastcgi_busy_buffers_size 128k;\n\n fastcgi_temp_file_write_size 128k;\n\n gzip on; \n\n gzip_min_length 1k;\n\n gzip_buffers 4 16k;\n\n gzip_http_version 1.0;\n\n gzip_comp_level 2;\n\n gzip_types text/plain application/x-javascript text/css application/xml;\n\n gzip_vary on;\n\n \n\n #limit_zone crawler $binary_remote_addr 10m;\n\n #下面是server虚拟主机的配置\n\n server\n\n {\n\n listen 80;#监听端口\n\n server_name localhost;#域名\n\n index index.html index.htm index.php;\n\n root /usr/local/webserver/nginx/html;#站点目录\n\n location ~ .*\\.(php|php5)?$\n\n {\n\n #fastcgi_pass unix:/tmp/php-cgi.sock;\n\n fastcgi_pass 127.0.0.1:9000;\n\n fastcgi_index index.php;\n\n include fastcgi.conf;\n\n }\n\n location ~ .*\\.(gif|jpg|jpeg|png|bmp|swf|ico)$\n\n {\n\n expires 30d;\n\n # access_log off;\n\n }\n\n location ~ .*\\.(js|css)?$\n\n {\n\n expires 15d;\n\n # access_log off;\n\n }\n\n access_log off;\n\n }\n\n}', 'bash', '', 0, 350, 0);
SET @u1880 := LAST_INSERT_ID();
