INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1891, 4, '正文', '', 'text', '将/etc/my.cnf替换为下面内容', 'bash', '', 0, 370, 0);
