INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1891, 4, '代码示例', '', 'code', '$ cat /etc/my.cnf\n\n[client]\n\nport = 3306\n\nsocket = /tmp/mysql.sock\n\n[mysqld]\n\nreplicate-ignore-db = mysql\n\nreplicate-ignore-db = test\n\nreplicate-ignore-db = information_schema\n\nuser = mysql\n\nport = 3306\n\nsocket = /tmp/mysql.sock\n\nbasedir = /usr/local/webserver/mysql\n\ndatadir = /www/data_mysql\n\nlog-error = /usr/local/webserver/mysql/mysql_error.log\n\npid-file = /usr/local/webserver/mysql/mysql.pid\n\nopen_files_limit = 65535\n\nback_log = 600\n\nmax_connections = 5000\n\nmax_connect_errors = 1000\n\ntable_open_cache = 1024\n\nexternal-locking = FALSE\n\nmax_allowed_packet = 32M\n\nsort_buffer_size = 1M\n\njoin_buffer_size = 1M\n\nthread_cache_size = 600\n\n#thread_concurrency = 8\n\nquery_cache_size = 128M\n\nquery_cache_limit = 2M\n\nquery_cache_min_res_unit = 2k\n\ndefault-storage-engine = MyISAM\n\ndefault-tmp-storage-engine=MYISAM\n\nthread_stack = 192K\n\ntransaction_isolation = READ-COMMITTED\n\ntmp_table_size = 128M\n\nmax_heap_table_size = 128M\n\nlog-slave-updates\n\nlog-bin = /usr/local/webserver/mysql/binlog/binlog\n\nbinlog-do-db=oa_fb\n\nbinlog-ignore-db=mysql\n\nbinlog_cache_size = 4M\n\nbinlog_format = MIXED\n\nmax_binlog_cache_size = 8M\n\nmax_binlog_size = 1G\n\nrelay-log-index = /usr/local/webserver/mysql/relaylog/relaylog\n\nrelay-log-info-file = /usr/local/webserver/mysql/relaylog/relaylog\n\nrelay-log = /usr/local/webserver/mysql/relaylog/relaylog\n\nexpire_logs_days = 10\n\nkey_buffer_size = 256M\n\nread_buffer_size = 1M\n\nread_rnd_buffer_size = 16M\n\nbulk_insert_buffer_size = 64M\n\nmyisam_sort_buffer_size = 128M\n\nmyisam_max_sort_file_size = 10G\n\nmyisam_repair_threads = 1\n\nmyisam_recover\n\ninteractive_timeout = 120\n\nwait_timeout = 120\n\nskip-name-resolve\n\n#master-connect-retry = 10\n\nslave-skip-errors = 1032,1062,126,1114,1146,1048,1396\n\n#master-host = 192.168.1.2\n\n#master-user = username\n\n#master-password = password\n\n#master-port = 3306\n\nserver-id = 1\n\nloose-innodb-trx=0 \n\nloose-innodb-locks=0 \n\nloose-innodb-lock-waits=0 \n\nloose-innodb-cmp=0 \n\nloose-innodb-cmp-per-index=0\n\nloose-innodb-cmp-per-index-reset=0\n\nloose-innodb-cmp-reset=0 \n\nloose-innodb-cmpmem=0 \n\nloose-innodb-cmpmem-reset=0 \n\nloose-innodb-buffer-page=0 \n\nloose-innodb-buffer-page-lru=0 \n\nloose-innodb-buffer-pool-stats=0 \n\nloose-innodb-metrics=0 \n\nloose-innodb-ft-default-stopword=0 \n\nloose-innodb-ft-inserted=0 \n\nloose-innodb-ft-deleted=0 \n\nloose-innodb-ft-being-deleted=0 \n\nloose-innodb-ft-config=0 \n\nloose-innodb-ft-index-cache=0 \n\nloose-innodb-ft-index-table=0 \n\nloose-innodb-sys-tables=0 \n\nloose-innodb-sys-tablestats=0 \n\nloose-innodb-sys-indexes=0 \n\nloose-innodb-sys-columns=0 \n\nloose-innodb-sys-fields=0 \n\nloose-innodb-sys-foreign=0 \n\nloose-innodb-sys-foreign-cols=0\n\nslow_query_log_file=/usr/local/webserver/mysql/mysql_slow.log\n\nlong_query_time = 1\n\n[mysqldump]\n\nquick\n\nmax_allowed_packet = 32M', 'bash', '', 0, 380, 0);
