INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1968, 4, '简介', '', 'text', 'Linux chattr 命令用于改变文件或目录的属性，这些属性可以控制文件系统的行为，提供更高级的文件管理功能。', 'bash', '', 0, 10, 0);
SET @u1969 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1968, 4, '语法', '', 'code', 'chattr [选项] [+/-/=属性] 文件或目录', 'bash', '', 0, 20, 0);
SET @u1970 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1968, 4, '参数与选项（7）', '', 'table', '[["a", "仅追加：文件只能追加内容，不能删除或修改已有内容（需 root 权限）。"], ["i", "不可变：文件不能被删除、修改、重命名或创建硬链接（需 root 权限）。"], ["A", "不更新文件的最后访问时间（atime）。"], ["c", "文件在磁盘上自动压缩（部分文件系统支持）。"], ["s", "安全删除：文件被删除时，其数据会被清零（不可恢复）。"], ["u", "文件被删除后，其内容仍可恢复（与 s 相反）。"], ["d", "文件在 dump 备份时会被跳过。"]]', 'bash', '', 0, 30, 0);
SET @u1971 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1968, 4, '添加属性（+）：', '', 'code', 'sudo chattr +i file.txt # 设置文件为不可变（防删除/修改）\n\nsudo chattr +a /var/log/syslog # 日志文件只能追加', 'bash', '', 0, 110, 0);
SET @u1972 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1968, 4, '移除属性（-）：', '', 'code', 'sudo chattr -i file.txt # 取消不可变属性', 'bash', '', 0, 120, 0);
SET @u1973 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1968, 4, '重置属性（=）：', '', 'code', 'sudo chattr =a file.txt # 移除所有属性，仅保留 `a`', 'bash', '', 0, 130, 0);
SET @u1974 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1968, 4, '保护重要配置文件：', '', 'code', 'chattr +i /etc/passwd\n\nchattr +i /etc/shadow', 'bash', '', 0, 140, 0);
SET @u1975 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1968, 4, '设置日志文件只能追加：', '', 'code', 'chattr +a /var/log/messages', 'bash', '', 0, 150, 0);
