INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1978, 4, '参数与选项（8）', '', 'table', '[["-c 或 --changes", "效果类似 \\"-v\\" 参数，但仅回报更改的部分。适合需要确认具体修改了哪些文件时使用。"], ["-f 或 --quiet 或 --silent", "不显示错误信息。当脚本需要静默执行时使用，避免大量错误输出干扰结果。"], ["-h 或 --no-dereference", "只对符号连接的文件作修改，而不改动其他任何相关文件。修改符号链接本身的所属组时必须使用。"], ["-R 或 --recursive", "递归处理，将指定目录下的所有文件及子目录一并处理。批量修改目录内所有文件时使用。"], ["-v 或 --verbose", "显示指令执行过程。用于调试或确认每个文件的修改状态。"], ["--help", "显示帮助信息，列出所有可用参数。"], ["--reference=<参考文件或目录>", "把指定文件或目录的所属群组全部设成和参考文件或目录的所属群组相同。用于批量复制权限场景。"], ["--version", "显示版本信息。"]]', 'bash', '', 0, 30, 0);
SET @u1981 := LAST_INSERT_ID();
