INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2016, 4, '实例 1', '', 'code', '[root@localhost test3]# diff log2014.log log2013.log \n\n3c3\n\n< 2014-03\n\n---\n\n> 2013-03\n\n8c8\n\n< 2013-07\n\n---\n\n> 2013-08\n\n11,12d10\n\n< 2013-11\n\n< 2013-12', 'bash', '', 0, 110, 0);
