INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2016, 4, '上面的"3c3"和"8c8"表示log2014.log和log20143log文件在3行和第8行内容有所不同；"11,12d10"表示第一个文件比第二个文件多了第11和12行。', '', 'code', '[root@localhost test3]# diff log2014.log log2013.log -y -W 50\n\n2013-01 2013-01\n\n2013-02 2013-02\n\n2014-03 | 2013-03\n\n2013-04 2013-04\n\n2013-05 2013-05\n\n2013-06 2013-06\n\n2013-07 2013-07\n\n2013-07 | 2013-08\n\n2013-09 2013-09\n\n2013-10 2013-10\n\n2013-11 <\n\n2013-12 <\n\n[root@localhost test3]# diff log2013.log log2014.log -y -W 50\n\n2013-01 2013-01\n\n2013-02 2013-02\n\n2013-03 | 2014-03\n\n2013-04 2013-04\n\n2013-05 2013-05\n\n2013-06 2013-06\n\n2013-07 2013-07\n\n2013-08 | 2013-07\n\n2013-09 2013-09\n\n2013-10 2013-10\n\n > 2013-11\n\n > 2013-12', 'bash', '', 0, 120, 0);
