INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2056, 4, '给文件创建软链接，为log2013.log文件创建软链接link2013，如果log2013.log丢失，link2013将失效：', '', 'code', 'ln -s log2013.log link2013', 'bash', '', 0, 110, 0);
