SET @u2061 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2056, 4, '输出：', '', 'code', '[root@localhost test]# ll\n\nlrwxrwxrwx 1 root root 11 12-07 16:01 link2013 -> log2013.log\n\n-rw-r--r-- 1 root bin 61 11-13 06:03 log2013.log\n\n[root@localhost test]# ln log2013.log ln2013\n\n[root@localhost test]# ll\n\nlrwxrwxrwx 1 root root 11 12-07 16:01 link2013 -> log2013.log\n\n-rw-r--r-- 2 root bin 61 11-13 06:03 ln2013\n\n-rw-r--r-- 2 root bin 61 11-13 06:03 log2013.log', 'bash', '', 0, 140, 0);
