INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2117, 4, '使用指令mread将盘"a:\\"中的所有内容复制到当前工作目录下，输入如下命令：', '', 'code', '$ mread a:\\* ./ #将a盘上的所有文件复制到当前工作目录', 'bash', '', 0, 110, 0);
SET @u2120 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2117, 4, '执行该命令前，可以先使用mdir命令查看原来的目录结构。执行mread之后，可使用ls命令再次查看复制之后的文件结构，结果如下所示：', '', 'code', '$ mdir -/ a:\\* #查看a盘中的文件 \n\nVolume in drive A has no label #加载信息 \n\nVolume Serial Number is 13D2~055C \n\nDirectory for A:/ #以下为目录信息 \n\n./TEST <DIR> 2011-08-23 16:59 \n\n#显示格式为文件名，目录大小，修改时间 \n\nAUTORUN.INF 265 2011-08-23 16:53 \n\nAUTORUN.BAT 43 2011-08-23 16:56 \n\n3 files 308 bytes #统计总大小 \n\n724 325 bytes free #剩余空间 \n\n$ mread A:\\* ./ #将a盘上所有文件复制到当前工作目录 \n\n$ ls #查看文件或子目录信息 \n\nTEST AUTORUN.INF AUTORUN.BAT #显示复制后的内容', 'bash', '', 0, 120, 0);
SET @u2121 := LAST_INSERT_ID();
