INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2122, 4, '使用该命令前后使用mdir命令查看并对比，得到结果如下：', '', 'code', '$ mdir -/ a:\\* #查看a盘中的文件 \n\nVolume in drive A has no label #加载信息 \n\nVolume Serial Number is 13D2~055C \n\nDirectory for A:\\ #以下为目录信息 \n\n./TEST <DIR> 2011-08-23 16:59 #文件名，目录大小，修改时间 \n\nAUTORUN.BAT 43 2011-08-23 16:56 \n\n3 files 308 bytes #统计总大小 \n\n724 325 bytes free #剩余空间 \n\n#将文件autorun.bat重命名为auto.bat \n\n$ mren a:\\autorun.bat auto.bat \n\n$ mdir -/ a:\\* #再次查看a盘中文件 \n\nVolume in drive A has no label #加载信息 \n\nVolume Serial Number is 13D2~055C \n\nDirectory for A:\\ #以下为目录信息 \n\n./TEST <DIR> 2011-08-23 16:59 #文件名目录大小 修改时间 \n\n#文件名被改为auto.bat，修改时间改为当前系统时间 \n\nAUTO.BAT 43 2011-08-23 16:56 \n\n3 files 308 bytes #统计总大小 \n\n724 325 bytes free #剩余空间', 'bash', '', 0, 120, 0);
SET @u2126 := LAST_INSERT_ID();
