INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2127, 4, '在命令提示符中直接输入mtools，可显示其所支持的MS-DOS命令，如下所示：', '', 'code', '$ mtools #显示所支持的MS-DOS命令 \n\nSupported commands: #命令列表 \n\nmattrib, mbadblocks, mcat, mcd, mclasserase, mcopy, mdel, mdeltree \n\nmdir, mdoctorfat, mdu, mformat, minfo, mlabel, mmd, mmount \n\nmpartition, mrd, mread, mmove, mren, mshowfat, mtoolstest, mtype \n\nmwrite, mzip', 'bash', '', 0, 110, 0);
