INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1958, 3, 'mtoolstest', '测试 mtools 配置', 'cmd', NULL, 'bash', 'mtoolstest #显示mtools 软件包当前的配置信息', 1, 300, 1);
SET @u2131 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2131, 4, '简介', '', 'text', 'Linux mtoolstest命令用于测试并显示mtools的相关设置。', 'bash', '', 0, 10, 0);
SET @u2132 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2131, 4, '语法', '', 'code', 'mtoolstest', 'bash', '', 0, 20, 0);
SET @u2133 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2131, 4, '在命令行中直接输入mtoolstest，即可显示mtools软件包当前的配置信息，结果如下：', '', 'code', '$ mtoolstest #显示mtools 软件包当前的配置信息 \n\ndrive J: #mtools软件包当前的配置信息列表 \n\n#fn=0 mode=0 builtin \n\nfile="/dev/sdb4" fat_bits=16 \n\ntracks=0 heads=0 sectors=0 hidden=0 \n\noffset=0x0 \n\npartition=0 \n\nmformat_only \n\ndrive Z: \n\n#fn=0 mode=0 builtin \n\nfile="/dev/sdb4" fat_bits=16 \n\ntracks=0 heads=0 sectors=0 hidden=0 \n\noffset=0x0 \n\npartition=0 \n\nmformat_only \n\ndrive X: \n\n#fn=0 mode=0 builtin \n\nfile="$DISPLAY" fat_bits=0 \n\ntracks=0 heads=0 sectors=0 hidden=0 \n\noffset=0x0 \n\npartition=0 \n\ndrive A: \n\n#fn=2 mode=128 defined in /etc/mtools.conf \n\nfile="/dev/fd0" fat_bits=0 \n\ntracks=0 heads=0 sectors=0 hidden=0 \n\noffset=0x0 \n\npartition=0 \n\nexclusive \n\ndrive B: \n\n#fn=2 mode=128 defined in /etc/mtools.conf \n\nfile="/dev/fd1" fat_bits=0 \n\ntracks=0 heads=0 sectors=0 hidden=0 \n\noffset=0x0 \n\npartition=0 \n\nexclusive \n\ndrive M: \n\n#fn=2 mode=0 defined in /etc/mtools.conf \n\nfile="/var/lib/dosemu/hdimage.first" fat_bits=0 \n\ntracks=0 heads=0 sectors=0 hidden=0 \n\noffset=0x80 \n\npartition=1 \n\ndrive N: \n\n#fn=2 mode=0 defined in /etc/mtools.conf \n\nfile="/var/lib/dosemu/fdimage" fat_bits=0 \n\ntracks=0 heads=0 sectors=0 hidden=0 \n\noffset=0x0 \n\npartition=0 \n\nmtools_fat_compatibility=0 \n\nmtools_skip_check=0 \n\nmtools_lower_case=0', 'bash', '', 0, 110, 0);
SET @u2134 := LAST_INSERT_ID();
