INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2141, 4, '使用 od 命令：', '', 'code', '$ od -b tmp\n\n0000000 141 142 143 144 145 146 040 147 012\n\n0000011', 'bash', '', 0, 120, 0);
