SET @u2177 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2176, 4, '语法', '', 'code', 'split [选项] [输入文件] [输出文件前缀]', 'bash', '', 0, 20, 0);
