INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2176, 4, '实例 1', '', 'code', '# 生成一个包含 5000 行的测试文件\n\n$ seq 1 5000 > data.txt\n\n# 每 1000 行拆分为一个小文件\n\n$ split -l 1000 data.txt part_\n\n# 查看生成的文件\n\n$ ls -lh part_*\n\n-rw-r--r-- 1 runoob runoob 3.9K May 19 14:30 part_aa\n\n-rw-r--r-- 1 runoob runoob 3.9K May 19 14:30 part_ab\n\n-rw-r--r-- 1 runoob runoob 3.9K May 19 14:30 part_ac\n\n-rw-r--r-- 1 runoob runoob 3.9K May 19 14:30 part_ad\n\n-rw-r--r-- 1 runoob runoob 3.9K May 19 14:30 part_ae', 'bash', '', 0, 110, 0);
SET @u2179 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2176, 4, '实例 2', '', 'code', '# 生成一个 10MB 的测试文件\n\n$ dd if=/dev/urandom of=test.bin bs=1M count=10\n\n# 按每 2MB 拆分\n\n$ split -b 2M test.bin chunk_\n\n# 查看拆分结果\n\n$ ls -lh chunk_*\n\n-rw-r--r-- 1 runoob runoob 2.0M May 19 14:32 chunk_aa\n\n-rw-r--r-- 1 runoob runoob 2.0M May 19 14:32 chunk_ab\n\n-rw-r--r-- 1 runoob runoob 2.0M May 19 14:32 chunk_ac\n\n-rw-r--r-- 1 runoob runoob 2.0M May 19 14:32 chunk_ad\n\n-rw-r--r-- 1 runoob runoob 2.0M May 19 14:32 chunk_ae', 'bash', '', 0, 120, 0);
SET @u2180 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2176, 4, '实例 3', '', 'code', '# 将文件均分为 3 份\n\n$ split -n 3 data.txt equal_\n\n# 查看各文件行数\n\n$ wc -l equal_*\n\n 1667 equal_aa\n\n 1667 equal_ab\n\n 1666 equal_ac\n\n 5000 total', 'bash', '', 0, 130, 0);
SET @u2181 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2176, 4, '实例 4', '', 'code', '# 使用数字后缀，并指定后缀长度为 3\n\n$ split -d -a 3 -l 1000 data.txt runoob_\n\n# 生成的文件名\n\n$ ls runoob_*\n\nrunoob_000 runoob_001 runoob_002 runoob_003 runoob_004', 'bash', '', 0, 140, 0);
SET @u2182 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2176, 4, '实例 5', '', 'code', '# 生成一个包含不同长度行的测试日志\n\n$ for i in $(seq 1 100); do echo "Line $i: RUNOOB testing data $(head -c $((RANDOM % 50 + 10)) /dev/urandom | base64)"; done > log.txt\n\n# 按 1KB 拆分，同时保持行完整性\n\n$ split -C 1K log.txt log_\n\n# 检查每个文件的最后一行是否完整（都以换行符结尾）\n\n$ for f in log_*; do echo "$f: $(tail -c 1 $f | xxd | grep -c \'0a\')"; done', 'bash', '', 0, 150, 0);
SET @u2183 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2176, 4, '实例 6', '', 'code', '# 合并所有拆分文件，还原为原始文件\n\n$ cat part_* > restored.txt\n\n# 验证合并后的内容与原始文件一致\n\n$ diff data.txt restored.txt && echo "文件一致，合并成功"\n\n文件一致，合并成功', 'bash', '', 0, 160, 0);
SET @u2184 := LAST_INSERT_ID();
