INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2224, 4, '输出信息如下：', '', 'code', '$ whereis -b bash #显示bash 命令的二进制程序 \n\nbash: /bin/bash /etc/bash.bashrc /usr/share/bash # bash命令的二进制程序的地址 \n\n$ whereis -m bash #显示bash 命令的帮助文件 \n\nbash: /usr/share/man/man1/bash.1.gz #bash命令的帮助文件地址', 'bash', '', 0, 140, 0);
