INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2231, 4, '将 A 盘根目录中的 autoexec.bat 复制到目前工作目录之下：', '', 'code', 'mcopy a:autoexec.bat .', 'bash', '', 0, 110, 0);
