SET @u2235 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2231, 4, '执行该命令前先使用mdir 命令查看原来的目录结构，执行mcopy 之后可使用ls 命令查看复制之后Linux系统中的文件结构，结果如下：', '', 'code', 'cmd@cmd-desktop:~$ mdir -/ a:\\* #查看A 盘中的文件 \n\nVolume in drive A has no label #加载信息 \n\nVolume Serial Number is 13D2~055C \n\nDirectory for A:/ #以下为目录信息 \n\n#文件名目录大小 修改时间 \n\n./TEST <DIR> 2009-09-23 16:59 \n\nAUTORUN.INF 265 2009-09-23 16:53 \n\nAUTORUN.BAT 43 2009-09-23 16:56 \n\n3 files 308 bytes #统计总大小 \n\n724 325 bytes free #剩余空间 \n\ncmd@cmd-desktop:~$ mcopy -/ A:\\* #将A盘上的所有文件复制到当前工作目录 \n\ncmd@cmd-desktop:~$ls \n\nTEST AUTORUN.INF AUTORUN.BAT #A盘中的内容复制到Linux文件系统结构中', 'bash', '', 0, 130, 0);
SET @u2236 := LAST_INSERT_ID();
