INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2263, 4, '1、简单读取', '', 'code', '#!/bin/bash\n\n#这里默认会换行 \n\necho "输入网站名: " \n\n#读取从键盘的输入 \n\nread website \n\necho "你输入的网站名是 $website" \n\nexit 0 #退出', 'bash', '', 0, 110, 0);
