INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2263, 4, '2、-p 参数，允许在 read 命令行中直接指定一个提示。', '', 'code', '#!/bin/bash\n\nread -p "输入网站名:" website\n\necho "你输入的网站名是 $website" \n\nexit 0', 'bash', '', 0, 130, 0);
