INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2263, 4, '3、-t 参数指定 read 命令等待输入的秒数，当计时满时，read命令返回一个非零退出状态。', '', 'code', '#!/bin/bash\n\nif read -t 5 -p "输入网站名:" website\n\nthen\n\n echo "你输入的网站名是 $website"\n\nelse\n\n echo "\\n抱歉，你输入超时了。"\n\nfi\n\nexit 0', 'bash', '', 0, 150, 0);
