INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u1958, 3, 'realpath', '显示文件的绝对路径', 'cmd', NULL, 'bash', 'realpath ./docs/../readme.txt', 1, 530, 1);
