INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2282, 4, '简介', '', 'text', 'realpath 是 Linux 系统中一个实用的命令行工具，用于解析文件或目录的绝对路径（绝对路径是指从根目录 / 开始的完整路径）。它会解析所有符号链接（symbolic links）并规范化路径中的 .（当前目录）和 ..（上级目录）引用。', 'bash', '', 0, 10, 0);
SET @u2283 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2282, 4, '语法', '', 'code', 'realpath [选项] 文件或目录...', 'bash', '', 0, 20, 0);
SET @u2284 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2282, 4, '参数与选项（9）', '', 'table', '[["-e 或 --canonicalize-existing", "只解析实际存在的路径（默认行为）"], ["-m 或 --canonicalize-missing", "解析路径，即使路径不存在"], ["-L 或 --logical", "解析符号链接时，不跟随符号链接"], ["-P 或 --physical", "解析符号链接时，跟随所有符号链接（默认行为）"], ["-q 或 --quiet", "静默模式，不显示错误信息"], ["--relative-to=DIR", "返回相对于指定目录的路径"], ["--relative-base=DIR", "只规范化指定目录下的路径部分"], ["-s 或 --strip 或 --no-symlinks", "不展开符号链接"], ["-z 或 --zero", "用 NUL 字符而非换行符分隔输出"]]', 'bash', '', 0, 30, 0);
SET @u2285 := LAST_INSERT_ID();
