INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2296, 4, '简介', '', 'text', 'install 是 Linux 系统中一个多功能文件安装工具，它结合了文件复制、权限设置和目录创建等功能于一体。与简单的 cp 命令相比，install 提供了更精细的控制能力，特别适合在脚本中用于程序安装和文件部署。', 'bash', '', 0, 10, 0);
SET @u2297 := LAST_INSERT_ID();
