SET @u2311 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2308, 4, '按回车键后，光标将在第一行闪烁，等待标准输入，此时输入字符，如"Hello Linux！"，再按回车键后第二行将出现与第一行相同内容，此时按Ctrl+C组合键可以退出。终端中显示的内容如下所示：', '', 'code', 'cmd@hdd-desktop:~$ colrm \n\nHello Linux! #输入Hello Linux！字符串 \n\nHello Linux! #输出刚才输入的字符串Hello Linux！', 'bash', '', 0, 120, 0);
SET @u2312 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2308, 4, '如想要删除第4 列之后的所有内容，可以使用如下命令：', '', 'code', 'colrm 4', 'bash', '', 0, 130, 0);
SET @u2313 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2308, 4, '类似于上例，此时标准输入等待输入，用户输入字符串按回车键后，将输出如下结果：', '', 'code', 'cmd@hdd-desktop:~$ colrm 4 \n\nHello Linux! #输入Hello Linux！字符串 \n\nHel #输出删除了第4列以后所有内容的字符串', 'bash', '', 0, 140, 0);
SET @u2314 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2308, 4, '删除指定列的内容。如删除第4列到第6列的内容，可使用如下命令：', '', 'code', 'colrm 4 6', 'bash', '', 0, 150, 0);
SET @u2315 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2308, 4, '输出的结果如下：', '', 'code', 'cmd@hdd-desktop:~$ colrm 4 6 \n\nHello Linux! #输入Hello Linux！字符串 \n\nHelLinux! #输出删除了从第4列到第6列字符的字符串', 'bash', '', 0, 160, 0);
