INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2322, 4, '使用csplit命令，输出结果如下：', '', 'code', '$ csplit testfile 2 \n\n13 #xx00文件字符个数 \n\n76 #xx01文件字符个数', 'bash', '', 0, 130, 0);
