INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2330, 4, '简介', '', 'text', 'Linux ed命令是文本编辑器，用于文本编辑。', 'bash', '', 0, 10, 0);
SET @u2331 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2330, 4, '语法', '', 'code', 'ed [-][-Gs][-p<字符串>][--help][--version][文件]', 'bash', '', 0, 20, 0);
SET @u2332 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2330, 4, '以下是一个 Linux ed 完整实例解析：', '', 'code', '$ ed <- 激活 ed 命令 \n\na <- 告诉 ed 我要编辑新文件 \n\nMy name is Titan. <- 输入第一行内容 \n\nAnd I love Perl very much. <- 输入第二行内容 \n\n. <- 返回 ed 的命令行状态 \n\ni <- 告诉 ed 我要在最后一行之前插入内容 \n\nI am 24. <- 将“I am 24.”插入“My name is Titan.”和“And I love Perl very much.”之间 \n\n. <- 返回 ed 的命令行状态 \n\nc <- 告诉 ed 我要替换最后一行输入内容 \n\nI am 24 years old. <- 将“I am 24.”替换成“I am 24 years old.”（注意：这里替换的是最后输的内容） \n\n. <- 返回 ed 的命令行状态 \n\nw readme.text <- 将文件命名为“readme.text”并保存（注意：如果是编辑已经存在的文件，只需要敲入 w 即可） \n\nq <- 完全退出 ed 编辑器', 'bash', '', 0, 110, 0);
SET @u2333 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2330, 4, '这是文件的内容是：', '', 'code', '$ cat readme.text \n\nMy name is Titan. \n\nI am 24 years old. \n\nAnd I love Perl vrey much.', 'bash', '', 0, 120, 0);
SET @u2334 := LAST_INSERT_ID();
