INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2348, 4, '简介', '', 'text', 'Linux fmt命令用于编排文本文件。', 'bash', '', 0, 10, 0);
SET @u2349 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2348, 4, '语法', '', 'code', 'fmt [-cstu][-p<列起始字符串>][-w<每列字符数>][--help][--version][文件...]', 'bash', '', 0, 20, 0);
SET @u2350 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2348, 4, '重排指定文件。如文件testfile共5 行文字，可以通过命令对该文件格式进行重排，其命令为：', '', 'code', 'fmt testfile', 'bash', '', 0, 110, 0);
SET @u2351 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2348, 4, '输出结果如下：', '', 'code', '$ fmt testfile #重排testfile 文件 \n\nhello Linux! Linux is a free Unix-type operating system. This is a \n\nLinux testfile! Linux Linux', 'bash', '', 0, 120, 0);
SET @u2352 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2348, 4, '将文件testfile重新排成85 个字符一行，并在标准输出设备上输出，其命令应该为：', '', 'code', 'fmt -w 85 testfile', 'bash', '', 0, 130, 0);
SET @u2353 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2348, 4, '为了对比，先使用cat 命令查看文件内容：', '', 'code', '$ cat testfile #查看testfile 文件的内容 \n\nhello Linux! \n\nLinux is a free Unix-type operating system. \n\nThis is a Linux testfile! \n\nLinux \n\nLinux', 'bash', '', 0, 140, 0);
SET @u2354 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2348, 4, '使用fmt命令重排之后，输出结果如下：', '', 'code', '$ fmt -w 85 testfile #指定重排宽度为85个字符 \n\nhello Linux! Linux is a free Unix-type operating system. This is a Linux testfile! \n\nLinux Linux', 'bash', '', 0, 150, 0);
SET @u2355 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2303, 3, 'fold', '按宽度换行文本', 'cmd', NULL, 'bash', 'fold -w 30 testfile', 2, 100, 1);
SET @u2356 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2356, 4, '简介', '', 'text', 'Linux fold命令用于限制文件列宽。', 'bash', '', 0, 10, 0);
SET @u2357 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2356, 4, '语法', '', 'code', 'fold [-bs][-w<每列行数>][--help][--version][文件...]', 'bash', '', 0, 20, 0);
SET @u2358 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2356, 4, '将一个名为testfile 的文件的行折叠成宽度为30，可使用如下命令：', '', 'code', 'fold -w 30 testfile', 'bash', '', 0, 110, 0);
SET @u2359 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2356, 4, '为了对比，先将testfile文件输出如下：', '', 'code', '$ cat testfile #查看testfile 中的内容 \n\nLinux networks are becoming more and more common, but \n\nsecurity is often an overlooked \n\nissue. Unfortunately, in today’s environment all networks \n\nare potential hacker targets, \n\nfrom top-secret military research networks to small home LANs. \n\nLinux Network Security focuses on securing Linux in a \n\nnetworked environment, where the \n\nsecurity of the entire network needs to be considered \n\nrather than just isolated machines. \n\nIt uses a mix of theory and practical techniques to \n\nteach administrators how to install and \n\nuse security applications, as well as how the \n\napplications work and why they are necessary.', 'bash', '', 0, 120, 0);
SET @u2360 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2356, 4, '然后使用fold命令折叠显示：', '', 'code', '$ fold -w 30 testfile #行折叠成宽度为30，显示testfile 文件 \n\nLinux networks are becoming mo \n\nre and more common, but securi \n\nty is often an overlooked issu \n\ne. Unfortunately, in today’s \n\nenvironment all networks are \n\npotential hacker targets, from \n\ntop-secret military research \n\nnetworks to small home LANs. \n\nLinux Network Security focuses \n\non securing Linux in a networ \n\nked environment, where the sec \n\nurity of the entire network ne \n\neds to be considered rather th \n\nan just isolated machines. It \n\nuses a mix of theory and pract \n\nical techniques to teach admin \n\nistrators how to install and u \n\nse security applications, as w \n\nell as how the applications wo \n\nrk and why they are necessary', 'bash', '', 0, 130, 0);
SET @u2361 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2303, 3, 'grep', '文本搜索工具', 'cmd', NULL, 'bash', 'grep hello file.txt', 2, 110, 1);
SET @u2362 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2362, 4, '简介', '', 'text', 'Linux grep (global regular expression) 命令用于查找文件里符合条件的字符串或正则表达式。', 'bash', '', 0, 10, 0);
SET @u2363 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2362, 4, '语法', '', 'code', 'grep [options] pattern [files]\n\n或\n\ngrep [-abcEFGhHilLnqrsvVwxy][-A<显示行数>][-B<显示列数>][-C<显示列数>][-d<进行动作>][-e<范本样式>][-f<范本文件>][--help][范本样式][文件或目录...]', 'bash', '', 0, 20, 0);
SET @u2364 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2362, 4, '1、在文件 file.txt 中查找字符串 "hello"，并打印匹配的行：', '', 'code', 'grep hello file.txt', 'bash', '', 0, 110, 0);
SET @u2365 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2362, 4, '2、在文件夹 dir 中递归查找所有文件中匹配正则表达式 "pattern" 的行，并打印匹配行所在的文件名和行号：', '', 'code', 'grep -r -n pattern dir/', 'bash', '', 0, 120, 0);
SET @u2366 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2362, 4, '3、在标准输入中查找字符串 "world"，并只打印匹配的行数：', '', 'code', 'echo "hello world" | grep -c world', 'bash', '', 0, 130, 0);
SET @u2367 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2362, 4, '4、在当前目录中，查找后缀有 file 字样的文件中包含 test 字符串的文件，并打印出该字符串的行。此时，可以使用如下命令：', '', 'code', 'grep test *file', 'bash', '', 0, 140, 0);
SET @u2368 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2362, 4, '结果如下所示：', '', 'code', '$ grep test test* #查找前缀有“test”的文件包含“test”字符串的文件 \n\ntestfile1:This a Linux testfile! #列出testfile1 文件中包含test字符的行 \n\ntestfile_2:This is a linux testfile! #列出testfile_2 文件中包含test字符的行 \n\ntestfile_2:Linux test #列出testfile_2 文件中包含test字符的行', 'bash', '', 0, 150, 0);
SET @u2369 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2362, 4, '5、以递归的方式查找符合条件的文件。例如，查找指定目录/etc/acpi 及其子目录（如果存在子目录的话）下所有文件中包含字符串"update"的文件，并打印出该字符串所在行的内容，使用的命令为：', '', 'code', 'grep -r update /etc/acpi', 'bash', '', 0, 160, 0);
SET @u2370 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2303, 3, 'ispell', '拼写检查工具', 'cmd', NULL, 'bash', 'ispell testfile', 2, 120, 1);
SET @u2371 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2371, 4, '简介', '', 'text', 'Linux ispell命令用于拼写检查程序。', 'bash', '', 0, 10, 0);
SET @u2372 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2371, 4, '语法', '', 'code', 'ispell [-aAbBClmMnNPStVx][-d<字典文件>][-L<行数>][-p<字典文件>][-w<非字母字符>][-W<字符串长度>][要检查的文件]', 'bash', '', 0, 20, 0);
SET @u2373 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2371, 4, '检查文件的拼写。例如，检查testfile文件，可使用如下命令：', '', 'code', 'ispell testfile', 'bash', '', 0, 110, 0);
SET @u2374 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2371, 4, '如果文件中出现可疑词汇，则第一个出现的可疑词汇以高亮显示，并在屏幕下方给出词汇的修改意见，以及ispell的操作命令。如下所示：', '', 'code', 'netwrks File: testfile \n\nLinux netwrks are becoming more and more common, but security is often an overlooked \n\nissue. Unfortunately \n\n0: networks \n\n[SP] <number> R)epl A)ccept I)nsert L)ookup U)ncap Q)uit e(X)it or ? for help', 'bash', '', 0, 120, 0);
SET @u2375 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2371, 4, '通过以上实例我们可以发现，文件testfile中有拼写错误，对该文件进行修改后需备份文件。此时使用如下命令：', '', 'code', 'ispell-b testfile #检查拼写错误的同时，备份文件', 'bash', '', 0, 130, 0);
SET @u2376 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2371, 4, '如果文件已经无拼写错误，则不显示任何信息，通过ls命令我们也可以查看到当前文件目录下产生了文件testfile的备份文件testfile.bak。查看结果如下所示：', '', 'code', '$ ls #以列表的形式查看当前目录下的文件 \n\nexamples.desktop testfile_1 testfile.bak xx01 模板图片 音乐 \n\ntestfile testfile1 testfile_2 xx00 公共的视频文档桌面', 'bash', '', 0, 140, 0);
SET @u2377 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2303, 3, 'jed', '文本编辑器 JED', 'cmd', NULL, 'bash', 'jed main.c #用jed编辑器打开main.c 文件', 2, 130, 1);
SET @u2378 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2378, 4, '简介', '', 'text', 'Linux jed命令用于编辑文本文件。', 'bash', '', 0, 10, 0);
SET @u2379 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2378, 4, '语法', '', 'code', 'jed [-2n][-batch][-f<函数>][-g<行数>][-i<文件>][-I<文件>][-s<字符串>][文件]', 'bash', '', 0, 20, 0);
SET @u2380 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2378, 4, 'jed主要用于编辑程序的源码，编辑源码时将以彩色高亮的方式显示程序的语法。例如使用jed编辑一个C语言的源代码文件，可使用如下命令：', '', 'code', 'jed main.c #用jed编辑器打开main.c 文件', 'bash', '', 0, 110, 0);
SET @u2381 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2378, 4, '输出结果如下：', '', 'code', 'F10 key ==> File Edit Mode Search Buffers Windows System Help #编辑器菜单 \n\n/*-*- linux-c-*-*/ #编辑区 \n\n#include <linux/mm.h> \n\n#include <linux/sysctl.h> \n\n#include <linux/nsproxy.h> \n\nstatic struct list_head * \n\nnet_ctl_header_lookup(struct ctl_table_root *root, struct nsproxy *namespaces) \n\n{ \n\nreturn &namespaces->net_ns->sysctl_table_headers; \n\n} \n\nstatic struct ctl_table_root net_sysctl_root = { \n\n.lookup = net_ctl_header_lookup, \n\n}; \n\nstatic int sysctl_net_init(struct net *net) \n\n{ \n\nINIT_LIST_HEAD(&net->sysctl_table_headers); \n\nreturn 0; \n\n} \n\n-----+(Jed 0.99.18U) Emacs: main.c (C) All 6:06pm----------------------------- \n\n#从左到右分别为jed版本编号、当前是模拟emacs编辑器、打开的文件名、现在的时间 \n\nloading /usr/share/jed/lib/modeinfo.slc', 'bash', '', 0, 120, 0);
SET @u2382 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2303, 3, 'joe', '文本编辑器 JOE', 'cmd', NULL, 'bash', 'joe main.c', 2, 140, 1);
SET @u2383 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2383, 4, '简介', '', 'text', 'Linux joe命令用于编辑文本文件。', 'bash', '', 0, 10, 0);
SET @u2384 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2383, 4, '语法', '', 'code', 'joe [-asis][-beep][-csmode][-dopadding][-exask][-force][-help][-keepup][-lightoff][-arking][-mid][-nobackups][-nonotice][-nosta][-noxon][-orphan][-backpath<目录>][-columns<栏位>][-lines<行数>][-pg<行数>][-skiptop<行数>][-autoindent crlf linums overwrite rdonly wordwrap][+<行数>][-indentc<缩排字符>][-istep<缩排字符数>][-keymap<按键配置文件>][-lmargin<栏数>][-rmargin<栏数>][-tab<栏数>][要编辑的文件]</p>', 'bash', '', 0, 20, 0);
SET @u2385 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2383, 4, '利用joe命令编辑文本文件。例如利用joe编辑C 语言源代码main.c，使用如下命令：', '', 'code', 'joe main.c', 'bash', '', 0, 110, 0);
SET @u2386 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2383, 4, '与jed类似，joe编辑器中C语言的语法也以彩色的方式显示。效果如下：', '', 'code', 'I A main.c (c) Row 1 Col 1 12:28 Ctrl-K H for help \n\n#上排从左至右分别为打开的文件名、光标所在行列数、现在时间、显示操作说明 \n\n/*-*- linux-c-*-*/ #编辑区 \n\n#include <linux/mm.h> \n\n#include <linux/sysctl.h> \n\n#include <linux/nsproxy.h> \n\nstatic struct list_head * \n\nnet_ctl_header_lookup(struct ctl_table_root *root, struct nsproxy *namespaces) \n\n{ \n\nreturn &namespaces->net_ns->sysctl_table_headers; \n\n} \n\nstatic struct ctl_table_root net_sysctl_root = { \n\n.lookup = net_ctl_header_lookup, \n\n}; \n\nstatic int sysctl_net_init(struct net *net) \n\n{ \n\nINIT_LIST_HEAD(&net->sysctl_table_headers); \n\nreturn 0; \n\n} \n\n** Joe\'s Own Editor v3.5 ** (utf-8) ** Copyright . 2006 ** #joe编辑区的版本及版权信息', 'bash', '', 0, 120, 0);
SET @u2387 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2303, 3, 'join', '合并文件中相同行', 'cmd', NULL, 'bash', 'join testfile_1 testfile_2', 2, 150, 1);
SET @u2388 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2388, 4, '简介', '', 'text', 'Linux join命令用于将两个文件中，指定栏位内容相同的行连接起来。', 'bash', '', 0, 10, 0);
SET @u2389 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2388, 4, '语法', '', 'code', 'join [-i][-a<1或2>][-e<字符串>][-o<格式>][-t<字符>][-v<1或2>][-1<栏位>][-2<栏位>][--help][--version][文件1][文件2]', 'bash', '', 0, 20, 0);
SET @u2390 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2388, 4, '然后以默认的方式比较两个文件，将两个文件中指定字段的内容相同的行连接起来，在终端中输入命令：', '', 'code', 'join testfile_1 testfile_2', 'bash', '', 0, 110, 0);
SET @u2391 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2388, 4, '首先查看testfile_1、testfile_2 中的文件内容：', '', 'code', '$ cat testfile_1 #testfile_1文件中的内容 \n\nHello 95 #例如，本例中第一列为姓名，第二列为数额 \n\nLinux 85 \n\ntest 30 \n\ncmd@hdd-desktop:~$ cat testfile_2 #testfile_2文件中的内容 \n\nHello 2005 #例如，本例中第一列为姓名，第二列为年份 \n\nLinux 2009 \n\ntest 2006', 'bash', '', 0, 120, 0);
SET @u2392 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2388, 4, '然后使用join命令，将两个文件连接，结果如下：', '', 'code', '$ join testfile_1 testfile_2 #连接testfile_1、testfile_2中的内容 \n\nHello 95 2005 #连接后显示的内容 \n\nLinux 85 2009 \n\ntest 30 2006', 'bash', '', 0, 130, 0);
SET @u2393 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2388, 4, '文件1与文件2的位置对输出到标准输出的结果是有影响的。例如将命令中的两个文件互换，即输入如下命令：', '', 'code', 'join testfile_2 testfile_1', 'bash', '', 0, 140, 0);
SET @u2394 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2388, 4, '最终在标准输出的输出结果将发生变化，如下所示：', '', 'code', '$ join testfile_2 testfile_1 #改变文件顺序连接两个文件 \n\nHello 2005 95 #连接后显示的内容 \n\nLinux 2009 85 \n\ntest 2006 30', 'bash', '', 0, 150, 0);
SET @u2395 := LAST_INSERT_ID();
