INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2396, 4, '原文件testfile中的内容如下：', '', 'code', '$ cat testfile #查看testfile 文件内容 \n\nHELLO LINUX! \n\nLinux is a free unix-type opterating system. \n\nThis is a linux testfile! \n\nLinux test', 'bash', '', 0, 120, 0);
