INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2396, 4, '在testfile文件中使用look命令查找以"L"开头的单词，结果如下：', '', 'code', '$ look L testfile #查找以“L”开头的单词 \n\nLinux is a free unix-type opterating system. #第二行以“L”开头，列出全句 \n\nLinux test #第四行以“L”开头，列出全句', 'bash', '', 0, 130, 0);
