SET @u2410 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2407, 4, '输出结果如下：', '', 'code', 'GNU nano 2.0.9 文件: testfile #从左到右分别为编辑器版本号、文件名 \n\n#编辑区 \n\nLinux networks are becoming more and more common, but security is often an over$ \n\nLinux Network Securty focuses on securing Linux in a networked environment, whe$ \n\n[ 已读取3 行] #以下为菜单栏 \n\n^G 求助^O 写入^R 读档^Y 上页^K 剪切文字^C 在标位置 \n\n^X 离开^J 对齐^W 搜寻^V 下页^U 还原剪切^T 拼写检查', 'bash', '', 0, 120, 0);
SET @u2411 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2303, 3, 'rgrep', '递归查找文本', 'cmd', NULL, 'bash', 'rgrep Hello *', 2, 190, 1);
SET @u2412 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2412, 4, '简介', '', 'text', 'Linux rgrep命令用于递归查找文件里符合条件的字符串。', 'bash', '', 0, 10, 0);
SET @u2413 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2412, 4, '语法', '', 'code', 'rgrep [-?BcDFhHilnNrv][-R<范本样式>][-W<列长度>][-x<扩展名>][--help][--version][范本样式][文件或目录...]', 'bash', '', 0, 20, 0);
SET @u2414 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2412, 4, '在当前目录下查找句子中包含"Hello"字符串的文件，可使用如下命令：', '', 'code', 'rgrep Hello *', 'bash', '', 0, 110, 0);
SET @u2415 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2412, 4, '其搜索结果如下：', '', 'code', '$ rgrep Hello * #在当前目录下查找句子中包含“Hello”字符串的文件 \n\ntestfile_1:Hello 95 #testfile_1中包含“Hello”字符串的句子 \n\ntestfile_2:Hello 2005 #testfile_2中包含“Hello”字符串的句子', 'bash', '', 0, 120, 0);
SET @u2416 := LAST_INSERT_ID();
