INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2417, 4, '简介', '', 'text', 'Linux sed 命令是利用脚本来处理文本文件。', 'bash', '', 0, 10, 0);
