INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2417, 4, '语法', '', 'code', 'sed [-hnV][-e<script>][-f<script文件>][文本文件]', 'bash', '', 0, 20, 0);
SET @u2419 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2417, 4, '我们先创建一个 testfile 文件，内容如下：', '', 'code', '$ cat testfile #查看testfile 中的内容 \n\nHELLO LINUX! \n\nLinux is a free unix-type opterating system. \n\nThis is a linux testfile! \n\nLinux test \n\nGoogle\n\nTaobao\n\nRunoob\n\nTesetfile\n\nWiki', 'bash', '', 0, 110, 0);
SET @u2420 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2417, 4, '在 testfile 文件的第四行后添加一行，并将结果输出到标准输出，在命令行提示符下输入如下命令：', '', 'code', 'sed -e 4a\\newLine testfile', 'bash', '', 0, 120, 0);
SET @u2421 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2417, 4, '使用 sed 命令后，输出结果如下：', '', 'code', '$ sed -e 4a\\newLine testfile \n\nHELLO LINUX! \n\nLinux is a free unix-type opterating system. \n\nThis is a linux testfile! \n\nLinux test \n\nnewLine\n\nGoogle\n\nTaobao\n\nRunoob\n\nTesetfile\n\nWiki', 'bash', '', 0, 130, 0);
SET @u2422 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2417, 4, '实例 4', '', 'code', '$ nl testfile | sed \'2,5d\'\n\n 1 HELLO LINUX! \n\n 6 Taobao\n\n 7 Runoob\n\n 8 Tesetfile\n\n 9 Wiki', 'bash', '', 0, 140, 0);
SET @u2423 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2417, 4, '实例 5', '', 'code', '$ nl testfile | sed \'2d\' \n\n 1 HELLO LINUX! \n\n 3 This is a linux testfile! \n\n 4 Linux test \n\n 5 Google\n\n 6 Taobao\n\n 7 Runoob\n\n 8 Tesetfile\n\n 9 Wiki', 'bash', '', 0, 150, 0);
SET @u2424 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2417, 4, '实例 6', '', 'code', '$ nl testfile | sed \'3,$d\' \n\n 1 HELLO LINUX! \n\n 2 Linux is a free unix-type opterating system.', 'bash', '', 0, 160, 0);
