INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2433, 4, '检查文件testfile是否有拼写错误，在命令行提示符下输入如下命令：', '', 'code', 'spell testfile', 'bash', '', 0, 110, 0);
