INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2433, 4, '如果文件中有单词拼写错误，则输出如下信息：', '', 'code', '$ spell testfile #检查testfile 拼写错误 \n\nscurity #以下为有错误的单词 \n\ntp \n\nLANs \n\nSecurty \n\npracticl \n\napplcations \n\nnecesary', 'bash', '', 0, 120, 0);
