INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2433, 4, '检查从标准输入读取的字符串。例如在命令行中输入如下命令：', '', 'code', 'spell', 'bash', '', 0, 130, 0);
SET @u2438 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2433, 4, '按回车键后，输入一串字符串，然后按Ctrl+D 组合键退出spell，屏幕上将显示拼写有错误的单词。如下所示：', '', 'code', '$ spell #检查标准输入的字符串的拼写错误 \n\nhell,this is a linx sustem! #拼写错误的字符串 \n\nlinx #以下为有拼写错误的单词 \n\nsustem', 'bash', '', 0, 140, 0);
