INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2455, 4, '检查文件并删除文件中重复出现的行，并在行首显示该行重复出现的次数。使用如下命令：', '', 'code', 'uniq -c testfile', 'bash', '', 0, 140, 0);
