INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2455, 4, '结果输出如下：', '', 'code', '$ uniq -c testfile #删除重复行后的内容 \n\n3 test 30 #前面的数字的意义为该行共出现了3次 \n\n4 Hello 95 #前面的数字的意义为该行共出现了4次 \n\n2 Linux 85 #前面的数字的意义为该行共出现了2次', 'bash', '', 0, 150, 0);
