INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2592, 4, '连接远程服务器"218.28.188.288"，然后使用put 命令下载其中根目录下的文件"README"，可使用命令如下：', '', 'code', 'tftp 218.28.188.288 #连接远程服务器', 'bash', '', 0, 150, 0);
SET @u2599 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2592, 4, '连接服务器之后可进行相应的操作，具体如下：', '', 'code', '$ tftp 218.28.188.228 #连接远程服务器 \n\ntftp> ? #使用？，参考帮助 \n\nCommands may be abbreviated. Commands are: #帮助命令列表 \n\nconnect connect to remote tftp \n\nmode set file transfer mode \n\nput send file \n\nget receive file \n\nquit exit tftp \n\nverbose toggle verbose mode \n\ntrace toggle packet tracing \n\nstatus show current status \n\nbinary set mode to octet \n\nascii set mode to netascii \n\nrexmt set per-packet retransmission timeout \n\ntimeout set total retransmission timeout \n\n? print help information \n\ntftp>get README #远程下载README文件 \n\ngetting from 218.28.188.288 to /home/cmd \n\nRecived 168236 bytes in 1.5 seconds[112157 bit/s] \n\ntftp>quit #离开tftp', 'bash', '', 0, 160, 0);
SET @u2600 := LAST_INSERT_ID();
