INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2610, 4, '简介', '', 'text', 'Linux ftpshut 命令在指定的时间关闭 FTP 服务器。', 'bash', '', 0, 10, 0);
