INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2610, 4, '语法', '', 'code', 'ftpshut [选项] [时间] [警告消息]', 'bash', '', 0, 20, 0);
SET @u2612 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2610, 4, '在晚上 11:00 关闭 FTP 服务器，并在关闭前 5 分钟拒绝新的 FTP 登录，前 3 分钟关闭所有 ftp 的链接，且给出警告信息，可使用如下命令：', '', 'code', 'ftpshut-d 3 -1 5 1100 "Server will be shutdown at 23:00:00"', 'bash', '', 0, 110, 0);
SET @u2613 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2610, 4, '假设你希望在 10 分钟后关闭 FTP 服务，并向用户发送一条警告消息，可以使用以下命令：', '', 'code', 'ftpshut +10 "FTP 服务将在 %s 关闭，请尽快完成操作。"', 'bash', '', 0, 120, 0);
SET @u2614 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2610, 4, '如果你希望在下午 3:00 关闭 FTP 服务，可以使用以下命令：', '', 'code', 'ftpshut 1500 "FTP 服务将在 %s 关闭，预计在 %r 重新启动。"', 'bash', '', 0, 130, 0);
SET @u2615 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2610, 4, '如果你希望在关闭 FTP 服务前 5 分钟拒绝新用户登录，可以使用以下命令：', '', 'code', 'ftpshut -l 5 +10 "FTP 服务将在 %s 关闭，请尽快完成操作。"', 'bash', '', 0, 140, 0);
