INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2610, 4, '如果你希望在关闭 FTP 服务前 2 分钟断开所有用户的连接，可以使用以下命令：', '', 'code', 'ftpshut -d 2 +10 "FTP 服务将在 %s 关闭，请尽快完成操作。"', 'bash', '', 0, 150, 0);
