INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2618, 4, '如果你的系统上运行了多个 FTP 服务实例，你可以通过指定服务类来查看特定服务的用户信息。例如：', '', 'code', 'ftpwho -s proftpd', 'bash', '', 0, 130, 0);
