INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2639, 4, '参数与选项（18）', '', 'table', '[["-a, --all", "显示所有文件系统，包括虚拟文件系统（如 proc, sysfs）"], ["-B, --block-size=SIZE", "指定显示单位（如 -BK=KB，-BM=MB，-BG=GB）"], ["-h, --human-readable", "以易读格式显示（自动转换单位：K, M, G, T，基于 1024）"], ["-H, --si", "类似 -h，但以 1000 为换算单位（符合 SI 标准）"], ["-i, --inodes", "显示 inode 使用情况（而非磁盘空间）"], ["-k", "以 1KB 为单位显示（默认单位）"], ["-m", "以 1MB 为单位显示（部分系统支持）"], ["-l, --local", "仅显示本地文件系统（排除网络文件系统如 NFS）"], ["--no-sync", "获取信息前不调用 sync（默认行为）"], ["--sync", "获取信息前调用 sync（确保数据最新）"], ["--total", "显示总计信息"], ["-t, --type=TYPE", "仅显示指定类型的文件系统（如 ext4, xfs）"], ["-T, --print-type", "显示文件系统类型"], ["-x, --exclude-type=TYPE", "排除指定类型的文件系统"], ["-P, --portability", "使用 POSIX 兼容的输出格式（避免换行问题）"], ["--output=FIELD_LIST", "自定义输出字段（如 source,fstype,size,pcent）"], ["--help", "显示帮助信息"], ["--version", "显示版本信息"]]', 'bash', '', 0, 30, 0);
SET @u2642 := LAST_INSERT_ID();
