INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2738, 4, '参数与选项（18）', '', 'table', '[["-a 或 --all", "显示所有文件（包括以 . 开头的隐藏文件）。"], ["-A 或 --almost-all", "显示除 . 和 .. 外的所有文件（包括隐藏文件）。"], ["-l", "以长格式（详细信息）列出文件（权限、所有者、大小、修改时间等）。"], ["-h 或 --human-readable", "与 -l 一起使用时，以人类可读的格式显示文件大小（如 KB、MB）。"], ["-t", "按修改时间排序（最新优先）。"], ["-r 或 --reverse", "反向排序（配合 -t、-S 等使用）。"], ["-S", "按文件大小排序（大文件优先）。"], ["-R 或 --recursive", "递归列出子目录内容。"], ["-F 或 --classify", "在文件名后附加标识符（如 / 表示目录，* 表示可执行文件）。"], ["--color", "彩色输出（通常默认启用，--color=auto）。"], ["-i 或 --inode", "显示文件的 inode 编号。"], ["-n 或 --numeric-uid-gid", "以数字形式显示 UID 和 GID（替代用户名和组名）。"], ["-d 或 --directory", "仅显示目录本身，而非其内容（常用于配合 -l）。"], ["-1", "每行只显示一个文件（默认在终端宽度不足时自动启用）。"], ["-m", "以逗号分隔的列表形式显示文件。"], ["-Q 或 --quote-name", "用引号括住文件名（适用于含空格的文件名）。"], ["--group-directories-first", "先显示目录，后显示文件。"], ["--time-style=<格式>", "自定义时间显示格式（如 +%Y-%m-%d）。"]]', 'bash', '', 0, 30, 0);
SET @u2741 := LAST_INSERT_ID();
