INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2766, 4, '例如，显示信息如下：', '', 'code', 'Disk /dev/sda: 298.9 GB, 298999349248 bytes\n\n255 heads, 63 sectors/track, 36351 cylinders\n\nUnits = cylinders of 16065 * 512 = 8225280 bytes\n\n Device Boot Start End Blocks Id System\n\n/dev/sda1 1 262 2104483+ 82 Linux swap / Solaris\n\n/dev/sda2 * 263 32898 262148670 83 Linux\n\n/dev/sda3 32899 36351 27736222+ 83 Linux\n\nDisk /dev/sdb: 42.9 GB, 42949672960 bytes\n\n64 heads, 32 sectors/track, 40960 cylinders\n\nUnits = cylinders of 2048 * 512 = 1048576 bytes', 'bash', '', 0, 120, 0);
