INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2779, 4, '将testfile文件中的所有英文字母转换为大写，然后转成为testfile_1文件，在命令提示符中使用如下命令：', '', 'code', 'dd if=testfile_2 of=testfile_1 conv=ucase', 'bash', '', 0, 120, 0);
SET @u2783 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2779, 4, '其中testfile_2 的内容为：', '', 'code', '$ cat testfile_2 #testfile_2的内容 \n\nHELLO LINUX! \n\nLinux is a free unix-type opterating system. \n\nThis is a linux testfile! \n\nLinux test', 'bash', '', 0, 130, 0);
SET @u2784 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2779, 4, '转换完成后，testfile_1 的内容如下：', '', 'code', '$ dd if=testfile_2 of=testfile_1 conv=ucase #使用dd 命令，大小写转换记录了0+1 的读入 \n\n记录了0+1 的写出 \n\n95字节（95 B）已复制，0.000131446 秒，723 KB/s \n\ncmd@hdd-desktop:~$ cat testfile_1 #查看转换后的testfile_1文件内容 \n\nHELLO LINUX! \n\nLINUX IS A FREE UNIX-TYPE OPTERATING SYSTEM. \n\nTHIS IS A LINUX TESTFILE! \n\nLINUX TEST #testfile_2中的所有字符都变成了大写字母', 'bash', '', 0, 140, 0);
SET @u2785 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2779, 4, '由标准输入设备读入字符串，并将字符串转换成大写后，再输出到标准输出设备，使用的命令为：', '', 'code', 'dd conv=ucase', 'bash', '', 0, 150, 0);
SET @u2786 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u2779, 4, '输入以上命令后按回车键，输入字符串，再按回车键，按组合键Ctrl+D 退出，出现以下结果：', '', 'code', '$ dd conv=ucase \n\nHello Linux! #输入字符串后按回车键 \n\nHELLO LINUX! #按组合键Ctrl+D退出，转换成大写结果 \n\n记录了0+1 的读入 \n\n记录了0+1 的写出 \n\n13字节（13 B）已复制，12.1558 秒，0.0 KB/s', 'bash', '', 0, 160, 0);
SET @u2787 := LAST_INSERT_ID();
