INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3248, 4, '显示进程信息：', '', 'code', '# ps -A \n\nPID TTY TIME CMD\n\n 1 ? 00:00:02 init\n\n 2 ? 00:00:00 kthreadd\n\n 3 ? 00:00:00 migration/0\n\n 4 ? 00:00:00 ksoftirqd/0\n\n 5 ? 00:00:00 watchdog/0\n\n 6 ? 00:00:00 events/0\n\n 7 ? 00:00:00 cpuset\n\n 8 ? 00:00:00 khelper\n\n 9 ? 00:00:00 netns\n\n 10 ? 00:00:00 async/mgr\n\n 11 ? 00:00:00 pm\n\n 12 ? 00:00:00 sync_supers\n\n 13 ? 00:00:00 bdi-default\n\n 14 ? 00:00:00 kintegrityd/0\n\n 15 ? 00:00:02 kblockd/0\n\n 16 ? 00:00:00 kacpid\n\n 17 ? 00:00:00 kacpi_notify\n\n 18 ? 00:00:00 kacpi_hotplug\n\n 19 ? 00:00:27 ata/0\n\n……省略部分结果\n\n30749 pts/0 00:00:15 gedit\n\n30886 ? 00:01:10 qtcreator.bin\n\n30894 ? 00:00:00 qtcreator.bin \n\n31160 ? 00:00:00 dhclient\n\n31211 ? 00:00:00 aptd\n\n31302 ? 00:00:00 sshd\n\n31374 pts/2 00:00:00 bash\n\n31396 pts/2 00:00:00 ps', 'bash', '', 0, 130, 0);
SET @u3253 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3248, 4, '显示指定用户信息', '', 'code', '# ps -u root //显示root进程用户信息\n\n PID TTY TIME CMD\n\n 1 ? 00:00:02 init\n\n 2 ? 00:00:00 kthreadd\n\n 3 ? 00:00:00 migration/0\n\n 4 ? 00:00:00 ksoftirqd/0\n\n 5 ? 00:00:00 watchdog/0\n\n 6 ? 00:00:00 events/0\n\n 7 ? 00:00:00 cpuset\n\n 8 ? 00:00:00 khelper\n\n 9 ? 00:00:00 netns\n\n 10 ? 00:00:00 async/mgr\n\n 11 ? 00:00:00 pm\n\n 12 ? 00:00:00 sync_supers\n\n 13 ? 00:00:00 bdi-default\n\n 14 ? 00:00:00 kintegrityd/0\n\n 15 ? 00:00:02 kblockd/0\n\n 16 ? 00:00:00 kacpid\n\n……省略部分结果\n\n30487 ? 00:00:06 gnome-terminal\n\n30488 ? 00:00:00 gnome-pty-helpe\n\n30489 pts/0 00:00:00 bash\n\n30670 ? 00:00:00 debconf-communi \n\n30749 pts/0 00:00:15 gedit\n\n30886 ? 00:01:10 qtcreator.bin\n\n30894 ? 00:00:00 qtcreator.bin \n\n31160 ? 00:00:00 dhclient\n\n31211 ? 00:00:00 aptd\n\n31302 ? 00:00:00 sshd\n\n31374 pts/2 00:00:00 bash\n\n31397 pts/2 00:00:00 ps', 'bash', '', 0, 140, 0);
SET @u3254 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3248, 4, '显示所有进程信息，连同命令行', '', 'code', '# ps -ef //显示所有命令，连带命令行\n\nUID PID PPID C STIME TTY TIME CMD\n\nroot 1 0 0 10:22 ? 00:00:02 /sbin/init\n\nroot 2 0 0 10:22 ? 00:00:00 [kthreadd]\n\nroot 3 2 0 10:22 ? 00:00:00 [migration/0]\n\nroot 4 2 0 10:22 ? 00:00:00 [ksoftirqd/0]\n\nroot 5 2 0 10:22 ? 00:00:00 [watchdog/0]\n\nroot 6 2 0 10:22 ? /usr/lib/NetworkManager\n\n……省略部分结果\n\nroot 31302 2095 0 17:42 ? 00:00:00 sshd: root@pts/2 \n\nroot 31374 31302 0 17:42 pts/2 00:00:00 -bash\n\nroot 31400 1 0 17:46 ? 00:00:00 /usr/bin/python /usr/sbin/aptd\n\nroot 31407 31374 0 17:48 pts/2 00:00:00 ps -ef', 'bash', '', 0, 150, 0);
