INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3143, 3, 'iotop', '监控磁盘 I/O 使用情况', 'cmd', NULL, 'bash', 'sudo iotop', 3, 530, 1);
SET @u3441 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3441, 4, '简介', '', 'text', 'iotop是一个类似于top命令的Linux系统监控工具，但它专注于显示磁盘I/O使用情况。它能实时监控系统中各个进程的磁盘读写活动，帮助系统管理员识别I/O密集型进程。', 'bash', '', 0, 10, 0);
SET @u3442 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3441, 4, '语法', '', 'code', 'sudo iotop [选项]', 'bash', '', 0, 20, 0);
SET @u3443 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3441, 4, '参数与选项（11）', '', 'table', '[["-o 或 --only", "只显示实际进行I/O操作的进程"], ["-b 或 --batch", "非交互式模式，适合脚本中使用"], ["-n NUM", "在非交互模式下运行的迭代次数"], ["-d SEC", "设置刷新间隔时间（秒）"], ["-p PID", "只监控指定PID的进程"], ["-u USER", "只监控指定用户的进程"], ["-P 或 --processes", "只显示进程，不显示线程"], ["-a 或 --accumulated", "显示累计I/O而不是带宽"], ["-k 或 --kilobytes", "使用KB/s而不是B/s作为单位"], ["-t 或 --time", "在输出中添加时间戳"], ["-q 或 --quiet", "减少头部信息（在非交互模式下自动启用）"]]', 'bash', '', 0, 30, 0);
SET @u3444 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3441, 4, '实例 1', '', 'code', 'sudo iotop', 'bash', '', 0, 110, 0);
SET @u3445 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3441, 4, '这会启动交互式界面，显示所有进程的I/O活动，按I/O使用量排序。', '', 'code', 'sudo iotop -o', 'bash', '', 0, 120, 0);
SET @u3446 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3441, 4, '或者运行iotop后按o键，只显示当前正在进行I/O操作的进程。', '', 'code', 'sudo iotop -u apache', 'bash', '', 0, 130, 0);
SET @u3447 := LAST_INSERT_ID();
