INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3451, 4, '简介', '', 'text', 'nethogs 是一个开源的 Linux 命令行工具，用于按进程实时监控网络带宽使用情况。与传统的网络监控工具（如 iftop）不同，nethogs 不是基于端口或协议来统计流量，而是直接显示每个进程的网络活动。', 'bash', '', 0, 10, 0);
SET @u3452 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3451, 4, '语法', '', 'code', 'sudo nethogs', 'bash', '', 0, 20, 0);
