INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3461, 4, '简介', '', 'text', 'dstat 是一个功能强大的 Linux 系统监控工具，它可以实时显示系统资源使用情况，包括 CPU、内存、磁盘、网络等关键指标。dstat 的设计目标是替代传统的 vmstat、iostat、netstat 等工具，提供一个统一的监控界面。', 'bash', '', 0, 10, 0);
