INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3704, 4, '删除环境变量', '', 'code', '[root@runoob.com ~]# lx="ls -lh" //设定环境变量\n\n[root@runoob.com ~]# $lx //使用环境变量\n\n总用量 116K\n\n-rw-r--r-- 1 root root 2.1K 2008-03-30 anaconda-ks.cfg\n\ndrwx------ 3 root root 4.0K 3月 30 21:22 Desktop\n\n-rw-r--r-- 1 root root 50K 2008-03-30 install.log\n\n-rw-r--r-- 1 root root 32K 2008-03-30 install.log.syslog\n\nlrwxrwxrwx 1 root root 9 2008-03-30 qte -> /opt/qte/\n\n[root@runoob.com ~]# set //查看当前的环境变量\n\nBASH=/bin/bash\n\nBASH_ARGC=()\n\nBASH_ARGV=()\n\n……省略部分内容\n\nPROMPT_COMMAND=\'echo -ne "33]0;${USER}@${HOSTNAME%%.*}:${PWD/#$HOME/~}07"\'\n\nPS1=\'[u@h W]$ \'\n\nPS2=\'> \'\n\nPS4=\'+ \'\n\nPWD=/root\n\nQTDIR=/usr/lib/qt-3.3\n\nSHELL=/bin/bash\n\nSSH_TTY=/dev/pts/4\n\nSUPPORTED=zh_CN.UTF-8:zh_CN:zh:en_US.UTF-8:en_US:en\n\nSYSFONT=latarcyrheb-sun16\n\nTERM=xterm\n\nUID=0\n\nUSER=root\n\n_=-lh\n\nlx=\'ls -lh\'\n\n[root@runoob.com ~]# unset lx //删除环境变量\n\n[root@runoob.com ~]# set //显示当前环境变量\n\nBASH=/bin/bash\n\nBASH_ARGC=()\n\nBASH_ARGV=()\n\n……省略部分内容\n\nPROMPT_COMMAND=\'echo -ne "33]0;${USER}@${HOSTNAME%%.*}:${PWD/#$HOME/~}07"\'\n\nPS1=\'[u@h W]$ \'\n\nPS2=\'> \'\n\nPS4=\'+ \'\n\nPWD=/root\n\nQTDIR=/usr/lib/qt-3.3\n\nSHELL=/bin/bash\n\nSSH_TTY=/dev/pts/4\n\nSUPPORTED=zh_CN.UTF-8:zh_CN:zh:en_US.UTF-8:en_US:en\n\nSYSFONT=latarcyrheb-sun16\n\nTERM=xterm\n\nUID=0\n\nUSER=root\n\n_=-lh', 'bash', '', 0, 110, 0);
SET @u3707 := LAST_INSERT_ID();
