INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3742, 4, '简介', '', 'text', 'Linux gpasswd 是 Linux 下工作组文件 /etc/group 和 /etc/gshadow 管理工具，用于将一个用户添加到组或者从组中删除。', 'bash', '', 0, 10, 0);
SET @u3743 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3742, 4, '语法', '', 'code', 'gpasswd [可选项] 组名', 'bash', '', 0, 20, 0);
SET @u3744 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3742, 4, '如系统有个 peter 账户，该账户本身不是 groupname 群组的成员，使用 newgrp 需要输入密码即可。', '', 'code', 'gpasswd groupname', 'bash', '', 0, 110, 0);
SET @u3745 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3742, 4, '所以使用 gpasswd groupname 设定密码，就是让知道该群组密码的人可以暂时切换具备 groupname 群组功能的。', '', 'code', 'gpasswd -A peter users', 'bash', '', 0, 120, 0);
SET @u3746 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3742, 4, '这样 peter 就是 users 群组的管理员，就可以执行下面的操作:', '', 'code', 'gpasswd -a mary users\n\ngpasswd -a allen users', 'bash', '', 0, 130, 0);
