INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3880, 4, '实例 1', '', 'code', '定义按键组合\n\n<pre>\n\n# loadkeys \n\ncontrol alt keycode 88 = F80 //现确定键代码\n\nstring F80="runoob.com" //给变变量设定值\n\n//按下 Ctrl + D键 确定输入\n\n//效果：按下 Ctrl +Alt + F12 输出 Lx138.Com\n\n# dumpkeys --funcs-only //显示功能键\n\n……省略部分结果\n\nstring F3 = "\\033[[C"\n\nstring F4 = "\\033[[D"\n\nstring F5 = "\\033[[E"\n\nstring F6 = "\\033[17~"\n\nstring F7 = "\\033[18~"\n\nstring F8 = "\\033[19~"\n\nstring F9 = "\\033[20~"\n\nstring F10 = "\\033[21~"\n\nstring F11 = "\\033[23~"\n\nstring F12 = "\\033[24~"\n\nstring F13 = "\\033[25~"\n\nstring F14 = "\\033[26~"\n\nstring F15 = "\\033[28~"\n\nstring F16 = "\\033[29~"\n\nstring F17 = "\\033[31~"\n\nstring F18 = "\\033[32~"\n\nstring F19 = "\\033[33~"\n\nstring F20 = "\\033[34~"\n\nstring Find = "\\033[1~"\n\nstring Insert = "\\033[2~"\n\nstring Remove = "\\033[3~"\n\nstring Select = "\\033[4~"\n\nstring Prior = "\\033[5~"\n\nstring Next = "\\033[6~"\n\nstring Macro = "\\033[M"\n\nstring Pause = "\\033[P"\n\nstring F80 = "runoob.com"', 'bash', '', 0, 110, 0);
SET @u3883 := LAST_INSERT_ID();
