INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3887, 4, '显示驱动信息', '', 'code', '# dumpkeys -i\n\n键值码范围被内核支持: 1 - 255\n\n可绑定到键值的动作最大值: 256\n\n实际使用的键值数: 128\n\n其中 121 已动态分配\n\n被内核支持的动作码值范围\n\n0x0000 - 0x00ff\n\n0x0100 - 0x01ff\n\n0x0200 - 0x0213\n\n0x0300 - 0x0313\n\n0x0400 - 0x0405\n\n0x0500 - 0x05ff\n\n0x0600 - 0x0603\n\n0x0700 - 0x0708\n\n0x0800 - 0x08ff\n\n0x0900 - 0x0919\n\n0x0a00 - 0x0a08\n\n0x0b00 - 0x0bff\n\n0x0c00 - 0x0c08\n\n0x0d00 - 0x0dff\n\n0x0e00 - 0x0e0a\n\n内核支持的功能键数：256\n\n编写定义的最大nr: 256\n\n实际使用的编写定义nr: 68', 'bash', '', 0, 120, 0);
