SET @u3932 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3930, 4, '实例 1', '', 'code', 'ip link show # 显示网络接口信息\n\nip link set eth0 up # 开启网卡\n\nip link set eth0 down # 关闭网卡\n\nip link set eth0 promisc on # 开启网卡的混合模式\n\nip link set eth0 promisc offi # 关闭网卡的混个模式\n\nip link set eth0 txqueuelen 1200 # 设置网卡队列长度\n\nip link set eth0 mtu 1400 # 设置网卡最大传输单元\n\nip addr show # 显示网卡IP信息\n\nip addr add 192.168.0.1/24 dev eth0 # 设置eth0网卡IP地址192.168.0.1\n\nip addr del 192.168.0.1/24 dev eth0 # 删除eth0网卡IP地址\n\nip route show # 显示系统路由\n\nip route add default via 192.168.1.254 # 设置系统默认路由\n\nip route list # 查看路由信息\n\nip route add 192.168.4.0/24 via 192.168.0.254 dev eth0 # 设置192.168.4.0网段的网关为192.168.0.254,数据走eth0接口\n\nip route add default via 192.168.0.254 dev eth0 # 设置默认网关为192.168.0.254\n\nip route del 192.168.4.0/24 # 删除192.168.4.0网段的网关\n\nip route del default # 删除默认路由\n\nip route delete 192.168.1.0/24 dev eth0 # 删除路由', 'bash', '', 0, 110, 0);
SET @u3933 := LAST_INSERT_ID();
INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u3930, 4, '用 ip 命令显示网络设备的运行状态：', '', 'code', '[root@localhost ~]# ip link list\n\n1: lo: <LOOPBACK,UP,LOWER_UP> mtu 16436 qdisc noqueue\n\n link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n\n2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc pfifo_fast qlen 1000\n\n link/ether 00:16:3e:00:1e:51 brd ff:ff:ff:ff:ff:ff\n\n3: eth1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc pfifo_fast qlen 1000\n\n link/ether 00:16:3e:00:1e:52 brd ff:ff:ff:ff:ff:ff', 'bash', '', 0, 120, 0);
SET @u3934 := LAST_INSERT_ID();
