INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u4116, 4, '简介', '', 'text', 'parted 是 Linux 系统中一个功能强大的磁盘分区工具，它支持多种分区表类型（如 GPT 和 MBR），能够创建、删除、调整和管理磁盘分区。与传统的 fdisk 相比，parted 特别适合处理大容量磁盘（超过 2TB）和现代分区需求。', 'bash', '', 0, 10, 0);
