INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u4270, 4, '简介', '', 'text', 'strace 是 Linux 系统下强大的诊断和调试工具，用于追踪程序执行期间的系统调用(system calls)和接收到的信号(signals)。系统调用是应用程序与操作系统内核交互的接口，通过 strace 我们可以深入了解程序的底层行为。', 'bash', '', 0, 10, 0);
SET @u4271 := LAST_INSERT_ID();
