INSERT INTO `units` (`parent_id`,`level`,`title`,`summary`,`content_type`,`body`,`lang`,`example`,`difficulty`,`sort_order`,`is_checkable`) VALUES (@u4328, 4, '简介', '', 'text', 'ldd（List Dynamic Dependencies）是 Linux 系统中一个非常有用的命令行工具，用于显示程序或共享库所依赖的动态链接库。当你在 Linux 上运行一个程序时，系统需要加载该程序依赖的各种共享库（.so 文件），ldd 就是用来查看这些依赖关系的工具。', 'bash', '', 0, 10, 0);
